  "공통 설정": "Gemeinsame Einstellungen",
  "입니다. 표시·아이콘·사용 패턴은 좌측 [뷰어 — TY Viewer]/[뷰어 — In Viewer] 탭에서 뷰어별로 설정하며, 기능은 두 뷰어 동일합니다.": ". Anzeige, Symbole und Nutzungsmuster werden links in den Tabs [Viewer — TY Viewer]/[Viewer — In Viewer] je Viewer eingestellt; die Funktionen sind in beiden Viewern identisch.",
  "영상 파이프라인": "Bildpipeline",
  "WASM 디코딩 파이프라인 (베타) — 원본 픽셀(WADO-RS bulkdata)을 브라우저에서 직접 디코딩": "WASM-Dekodierungspipeline (Beta) — Originalpixel (WADO-RS Bulkdata) direkt im Browser dekodieren",
  "켜면 2D 뷰어가 서버 렌더링(JPEG) 대신 원본 16bit 프레임을 받아 WASM 코덱으로 디코딩합니다. W/L 조정이 서버 왕복 없이 즉시 반영되고, 병원 설정의 전송구문(JPEG2000/JPEG-LS)으로 수신합니다. 디코딩 전에는 서버 렌더링으로 표시(자동 폴백).": "Aktiviert empfängt der 2D-Viewer statt Server-Rendering (JPEG) originale 16-Bit-Frames und dekodiert sie per WASM-Codec. W/L-Anpassungen wirken sofort ohne Server-Roundtrip; empfangen wird mit der Transfersyntax der Krankenhauseinstellungen (JPEG2000/JPEG-LS). Vor der Dekodierung wird das Server-Rendering angezeigt (automatischer Fallback).",
  "제품 모드 프로파일 (05 Mode Profile — 서버 JSON)": "Produktmodus-Profil (05 Mode Profile — Server-JSON)",
  "모드 선택…": "Modus wählen…",
  "현재 적용": "Aktuell angewendet",
  "모드 적용 — 왼쪽 ⟳ Refresh로 즉시 확인": "Modus angewendet — mit ⟳ Refresh links sofort prüfen",
