  "프로파일에 저장할까요? (전역 — 모든 사용자에게 적용)": "speichern? (Global — gilt für alle Benutzer)",
  "프로파일에 저장했습니다 (전역)": "im Profil gespeichert (global)",
  "현재 화면을 프로파일에 저장": "Aktuelle Ansicht im Profil speichern",
  "Core 기능은 동일, 화면 구성(컬럼·검색필드·팔레트/썸네일 배치·더블클릭·선택 뷰어)만 제품별 프로파일로 전환 — 타 PACS 사용 경험 그대로 이전. 프로파일 정의는 서버 전역 설정(mode.profiles)에서 로드.": "Kernfunktionen bleiben gleich; nur die Ansichtskonfiguration (Spalten, Suchfelder, Palette/Thumbnails, Doppelklick, gewählter Viewer) wechselt per Produktprofil — die gewohnte Bedienung anderer PACS bleibt erhalten. Profildefinitionen werden aus der globalen Servereinstellung (mode.profiles) geladen.",
