  "모든 뷰어(SaintView·T-View·I-View)의 워크리스트와": "Gilt für die Worklist aller Viewer (SaintView, T-View, I-View) und",
  "Live 모드에도 함께": "auch im Live-Modus",
  "적용됩니다. 수동일 때 원격에 변경이 생기면 목록을 바꾸지 않고 상단에 알림만 띄웁니다.": ". Bei manueller Aktualisierung wird die Liste bei Remote-Änderungen nicht geändert, sondern nur oben ein Hinweis angezeigt.",
  "초는 매우 짧습니다 — Live 모드에서는 원격 PACS 에 그만큼 자주 질의합니다.": "Sekunden sind sehr kurz — im Live-Modus wird das Remote-PACS entsprechend häufig abgefragt.",
