  "최근 환자 순": "der neuesten Patienten",
  "으로 훑어 시리즈 썸네일 → 각 시리즈의 이미지 순서로 미리 받아 둡니다. 저장 위치는 브라우저 전용 영역이라": "durch und lädt Serien-Thumbnails → dann die Bilder jeder Serie vorab. Der Speicherort ist ein browserinterner Bereich und",
  "탐색기에 보이지 않고 권한 프롬프트도 없습니다": "im Datei-Explorer nicht sichtbar, ohne Berechtigungsabfragen",
  ". 받아 둔 검사는 서버 왕복 없이 열립니다.": ". Vorab geladene Untersuchungen öffnen ohne Server-Roundtrip.",
  "⚠ 현재는": "⚠ Funktioniert derzeit nur im",
  "Live 모드 + 2D 뷰어(SaintView·T-View·I-View)": "Live-Modus + 2D-Viewer (SaintView, T-View, I-View)",
  "에서만 동작합니다. W/L 을 조정하는 동안에는 서버 렌더로 자동 폴백합니다(저장본은 검사 기본 W/L 로 구운 영상이라 그대로 쓰면 표시 W/L 과 실제 영상이 어긋납니다).": ". Während der W/L-Anpassung erfolgt automatisch ein Fallback auf das Server-Rendering (die gespeicherten Bilder sind mit dem Standard-W/L der Untersuchung gerendert und würden sonst vom angezeigten W/L abweichen).",
  "로그아웃·세션 만료 시 받아 둔 영상은 전부 삭제됩니다": "Bei Abmeldung oder Sitzungsablauf werden alle vorab geladenen Bilder gelöscht",
