  "더 받지 않습니다": "nichts mehr geladen",
  ". 계속 받다가 브라우저 할당량이 차면 브라우저가 받아 둔 영상을": ". Würde weiter geladen und das Browser-Kontingent voll, würde der Browser die vorab geladenen Bilder",
