  "자동으로 다시 받지 않습니다": "nicht automatisch erneut geladen",
  "그 검사를 워크리스트에서 열면 그때 다시 받습니다(상한·삭제 기준을 바꾸거나 [지금 비우기] 를 눌러도 초기화됩니다).": "Beim Öffnen der Untersuchung aus der Worklist wird sie erneut geladen (auch das Ändern von Limit/Löschkriterium oder [Jetzt leeren] setzt dies zurück).",
  "상한 근접 알림": "Hinweis bei Annäherung ans Limit",
