  "% 를 넘으면 알립니다 —": "% überschreitet, wird benachrichtigt —",
  "다운로드가 곧 중지될 때만": "nur wenn der Download bald stoppt",
  "뜹니다(자동 삭제가 꺼져 있거나, 열려 있는 검사만으로 상한을 넘어 지울 것이 없을 때). 자동 삭제가 정상 작동 중이면 사용량이 상한에 붙어 있는 것이 정상이라 알리지 않습니다. 워크리스트 창에서 1회 — 판독 중인 뷰어 창에는 띄우지 않습니다.": "(wenn automatisches Löschen aus ist oder allein die offenen Untersuchungen das Limit überschreiten und nichts gelöscht werden kann). Bei funktionierendem automatischem Löschen ist eine Auslastung nahe dem Limit normal und es erfolgt kein Hinweis. Einmalig im Worklist-Fenster — nicht in Viewer-Fenstern während der Befundung.",
