  "(원격 PACS 공용). 서버가 이미 검사마다 8워커로 예열하므로 2 를 권합니다.": "(gemeinsames Remote-PACS). Der Server wärmt bereits mit 8 Workern pro Untersuchung vor, daher wird 2 empfohlen.",
