  "Compare — 비교할 과거 검사를 어디서 고를까": "Compare — woher sollen die Voruntersuchungen für den Vergleich kommen?",
  "같은 환자(차트번호)의 과거 검사에서 고릅니다. 판독 비교의 기본입니다.": "Auswahl aus Voruntersuchungen desselben Patienten (Aktennummer). Standard für den Befundvergleich.",
  "내가 판독했던 검사 전체에서 고릅니다 — 환자가 달라도 됩니다. 내가 이미 판독하며 본 검사만 모집단이라 새로 열리는 자료는 없습니다.": "Auswahl aus allen von mir befundeten Untersuchungen — auch anderer Patienten. Grundgesamtheit sind nur bereits von mir befundete Untersuchungen; es werden keine neuen Daten erschlossen.",
  "좁히기": "Eingrenzen",
