  "으로 좁힙니다. 아무것도 체크하지 않으면 모집단 전체입니다.": "eingegrenzt. Ohne Auswahl gilt die gesamte Grundgesamtheit.",
  "예) Chest CT 판독 중 · 판독의사 기준 · 둘 다 체크 → 내가 판독한": "Beispiel: Thorax-CT in Befundung · nach Befunder · beide markiert → von mir befundete",
