  "지금 보는 검사의 검사일": "das Untersuchungsdatum der aktuell betrachteten Untersuchung",
  "입니다 — 예전 검사를 되짚어 판독할 때 '오늘로부터 1년'은 의미가 없기 때문입니다.": "— beim Nachbefunden älterer Untersuchungen wäre '1 Jahr ab heute' bedeutungslos.",
