  "다중 모니터 배치 — Viewer 모니터가 2개 이상이면 비교검사를 다음 모니터에 (끝번→첫 모니터 순환)": "Multi-Monitor-Anordnung — bei 2+ Viewer-Monitoren Vergleichsuntersuchung auf dem nächsten Monitor (letzter→erster im Zyklus)",
