  "(녹색·중앙 상단)": "(grün, oben mittig)",
  "과거검사(History) 비교 표시": "Vergleichsanzeige der Voruntersuchungen (History)",
  "Layout 띄우기 — 한 화면 1:2 분할 (좌=현재, 우=과거)": "Als Layout — 1:2-Teilung auf einem Bildschirm (links=aktuell, rechts=Vor)",
  "Monitor 띄우기 — 인접 모니터 창 (다음, 끝번이면 이전)": "Auf Monitor — Fenster auf benachbartem Monitor (nächster, beim letzten der vorherige)",
  "판독 도크 History의 과거검사(Prior Studies) 썸네일 클릭 시 적용. Monitor 띄우기 예: 모니터 1·2·3에서 3번 기준→2번, 1번 기준→2번에 표시. 조건 미충족(단일 모니터·감지/팝업 차단) 시 Layout 1:2로 폴백. ⇄ Compare(다중 선택)의 다중 모니터 배치는 위 체크가 담당합니다. 창 관리 권한(HTTPS)·팝업 허용 필요.": "Gilt beim Klick auf Prior-Studies-Thumbnails im History-Bereich des Befund-Docks. Beispiel 'Auf Monitor': bei Monitoren 1/2/3 wird von 3 aus auf 2, von 1 aus auf 2 angezeigt. Bei Nichterfüllung (einzelner Monitor, Erkennung/Pop-up blockiert) Fallback auf Layout 1:2. Für die Multi-Monitor-Anordnung von ⇄ Compare (Mehrfachauswahl) ist das obige Häkchen zuständig. Fensterverwaltungsberechtigung (HTTPS) und Pop-up-Freigabe erforderlich.",
  "시스템 단축키": "Systemkürzel",
  "기본값으로 초기화": "Auf Standardwerte zurücksetzen",
  "리포트 저장": "Report speichern",
  "리포트 승인": "Report freigeben",
  "음성 판독 (STT) 토글": "Sprachbefundung (STT) umschalten",
  "옵션·단축키는 OK(저장) 시 계정에 저장(로밍) — 뷰어 판독 창에 즉시 적용됩니다.": "Optionen/Kürzel werden bei OK (Speichern) im Konto gespeichert (Roaming) — sofort im Befundfenster des Viewers wirksam.",
  "워크리스트 — 뷰어별 그리드 컬럼 (계정별 저장)": "Worklist — Grid-Spalten je Viewer (pro Konto gespeichert)",
  "공통 워크리스트 설정 사용 (기본) — 해제하면 이 뷰어 전용 컬럼 구성을 편집합니다": "Gemeinsame Worklist-Einstellungen verwenden (Standard) — deaktiviert wird eine viewer-spezifische Spaltenkonfiguration bearbeitet",
  "모드로 워크리스트를 열면 이 구성이 공통 설정 대신 적용됩니다. OK(저장) 시 반영.": "Beim Öffnen der Worklist in diesem Modus gilt diese Konfiguration statt der gemeinsamen Einstellungen. Wirksam bei OK (Speichern).",
  "워크리스트 — 구성요소 표시/숨김 (화면 드래그·✕ 와 동기)": "Worklist — Komponenten ein-/ausblenden (synchron mit Drag/✕ am Bildschirm)",
  "해제 = 워크리스트에서 숨김. 화면에서 스플리터를 최소까지 드래그하거나 ✕(패널 그립)로 숨긴 상태가 여기와 양방향으로 동기됩니다.": "Abgewählt = in der Worklist ausgeblendet. Das Ausblenden per Splitter (bis zum Minimum ziehen) oder ✕ (Panel-Griff) wird bidirektional mit dieser Einstellung synchronisiert.",
  "그리드 컬럼 구성 — Filter Setting (USE/NO USE, UBPACS형)": "Grid-Spaltenkonfiguration — Filter Setting (USE/NO USE, UBPACS-Stil)",
  "USE/NO USE 클릭으로 토글, ▲▼로 표시 순서 변경 — OK(저장) 시 적용.": "Mit Klick auf USE/NO USE umschalten, Reihenfolge mit ▲▼ ändern — wirksam bei OK (Speichern).",
  "검색 필드 구성 (Find criteria)": "Suchfeldkonfiguration (Find criteria)",
