  "워크리스트 상용구(Std) 패널과 동일 DB — 리포트에서 Alt+단축키로 즉시 삽입.": "Gleiche DB wie das Textbaustein-Panel (Std) der Worklist — im Report per Alt+Kürzel sofort einfügen.",
  "워크리스트 구성요소 (UBPACS-Z p.8 — Study List 제외 추가/삭제)": "Worklist-Komponenten (UBPACS-Z S. 8 — Hinzufügen/Entfernen außer Study List)",
  "체크 해제 시 워크리스트에서 해당 창이 숨겨집니다. 배치 순서는 워크리스트에서 그립(⋮) 드래그로 변경.": "Abgewählte Fenster werden in der Worklist ausgeblendet. Reihenfolge in der Worklist per Griff (⋮) und Drag ändern.",
