  "워크리스트 탭의 상용구 관리": "die Textbausteinverwaltung im Worklist-Tab",
  "또는 워크리스트 하단 상용구(Std) 패널에서. 더블클릭 또는 Alt+단축키로 Conclusion에 삽입됩니다.": "oder das Textbaustein-Panel (Std) unten in der Worklist. Per Doppelklick oder Alt+Kürzel in die Conclusion einfügen.",
