  "끄면 워크리스트(⌂ Adv·🌐·우클릭 메뉴)와 뷰어의 OHIF 버튼이 숨겨지고 동작하지 않습니다. 더블클릭 동작이 OHIF 로 설정돼 있어도 자체 뷰어로 열립니다.": "Deaktiviert werden die OHIF-Schaltflächen in Worklist (⌂ Adv, 🌐, Kontextmenü) und Viewer ausgeblendet und funktionieren nicht. Auch bei Doppelklick-Einstellung OHIF wird der eigene Viewer geöffnet.",
