  "워크리스트를 해당 모니터로 열기": "Worklist auf diesem Monitor öffnen",
  "(브라우저 보안상 현재 창은 이동 불가 — 새 창으로 엽니다)": "(Aus Browser-Sicherheitsgründen kann das aktuelle Fenster nicht verschoben werden — es wird ein neues Fenster geöffnet)",
  "사용 방법:": "Verwendung:",
  "① 모니터 감지 → 🔢 모니터 확인(각 화면에 번호 표시·목록 번호와 대조) → ② 창별 모니터 지정 → ③ 하단": "① Monitore erkennen → 🔢 Monitore prüfen (Nummern auf jedem Bildschirm anzeigen, mit der Liste abgleichen) → ② Monitore je Fenster zuweisen → ③ unten",
  "→ ④ 다음 오픈부터 적용.": "→ ④ gilt ab dem nächsten Öffnen.",
  ": 1대=해당 모니터 / 2대 이상=아래 규칙 / 0대=기본 크기": ": 1 Monitor=dieser Monitor / ab 2=Regeln unten / 0=Standardgröße",
  "첫 영상(뷰어 창이 하나도 없을 때)은 선택한 모든 모니터에 같은 검사": "Das erste Bild (wenn kein Viewer-Fenster offen ist) öffnet mit derselben Untersuchung auf allen gewählten Monitoren",
  "로 뜹니다.": ".",
  "두 번째 영상부터는 모니터 번호순으로 한 대씩": "Ab dem zweiten Bild wechselt es der Monitornummer nach jeweils einen Monitor weiter",
  "바뀝니다(2,3,…,1,2,3…).": "(2,3,…,1,2,3…).",
  "검사가 열리는 그 모니터만 새로 로드되고, 나머지 모니터 뷰어는": "Nur der Monitor, auf dem die Untersuchung öffnet, wird neu geladen; die übrigen Viewer erhalten",
  "깜빡임 없이 Exam 탭만 추가": "ohne Flackern nur einen neuen Exam-Tab",
  "됩니다.": ".",
  "순환할 모니터 수는 위": "Die Anzahl rotierender Monitore wird oben über",
  "최대 열 영상 수": "Maximale Anzahl offener Bildfenster",
  "로 조절(0=선택 전부). 이 값은": "eingestellt (0=alle gewählten). Dieser Wert gilt",
  "순환 범위에만": "nur für den Rotationsumfang",
  "적용됩니다 — Compare·과거검사 '모니터 띄우기'는 선택한 모니터 전부를 쓰되": "— Compare und 'Auf Monitor' für Voruntersuchungen nutzen alle gewählten Monitore, wobei",
  "지금 검사가 떠 있는 모니터는 뒤로 미뤄": "Monitore mit aktuell angezeigter Untersuchung zurückgestellt werden und",
  "비어 있는 모니터부터 사용합니다. 순서는 워크리스트를 새로고침해도": "freie Monitore zuerst verwendet werden. Die Reihenfolge bleibt auch nach Aktualisierung der Worklist anhand",
  "살아 있는 뷰어 창": "der aktiven Viewer-Fenster",
  "을 기준으로 이어집니다. 최초 오픈은 창을 여러 개 동시에 열므로 팝업이 차단되면 주소창 팝업 아이콘에서 이 사이트": "erhalten. Das erste Öffnen startet mehrere Fenster gleichzeitig; bei Pop-up-Blockade diese Website über das Pop-up-Symbol der Adressleiste auf",
  "항상 허용": "Immer zulassen",
  "으로 설정하세요.": "setzen.",
  ": 위 버튼으로 해당 모니터에 새 창 오픈 (라디오 재클릭=해제)": ": mit der Schaltfläche oben ein neues Fenster auf diesem Monitor öffnen (Radio erneut klicken=aufheben)",
  ": 뷰어의 [Reading] 버튼이 해당 모니터에 판독 창을 띄움": ": die [Reading]-Schaltfläche des Viewers öffnet das Befundfenster auf diesem Monitor",
  "뷰어 창 정보 (별도 포트)": "Viewer-Fenster-Info (separater Port)",
  "현재 뷰어 창 출처:": "Quelle des aktuellen Viewer-Fensters:",
  "워크리스트와 동일 (같은 포트)": "Wie Worklist (gleicher Port)",
  "뷰어를 별도 포트로 분리하려면": "Um den Viewer auf einen separaten Port auszulagern,",
