  "를 함께 실행하세요 (재기동 필요).": "gemeinsam ausführen (Neustart erforderlich).",
  "탐색 방향 정책 — ◀▶ 환자 이동 (뷰어·판독 창·워크리스트 공통)": "Navigationsrichtungs-Richtlinie — ◀▶ Patientenwechsel (Viewer, Befundfenster, Worklist gemeinsam)",
