  "시간상 최신으로 (워크리스트 위 행 방향)": "Zeitlich nach vorn (in der Worklist nach oben)",
  "워크리스트는 최신 검사가 위에 정렬됩니다. ◀▶는 열려 있는 환자(현재 보고 있는 검사)를 기준으로": "In der Worklist stehen die neuesten Untersuchungen oben. ◀▶ bewegt sich ausgehend vom geöffneten Patienten (aktuell betrachtete Untersuchung)",
  "시간대별 한 단계씩": "zeitlich um jeweils einen Schritt",
  "이동하며, ▶(오른쪽)는 항상 ◀의 반대 방향입니다.": "; ▶ (rechts) ist immer die Gegenrichtung von ◀.",
  "과거로(기본)": "Zurück (Standard)",
  ": ◀=한 단계 과거(아래 행) / ▶=한 단계 최신(위 행)": ": ◀=ein Schritt zurück (Zeile darunter) / ▶=ein Schritt vor (Zeile darüber)",
  "최신으로": "Nach vorn",
  ": ◀=한 단계 최신(위 행) / ▶=한 단계 과거(아래 행)": ": ◀=ein Schritt vor (Zeile darüber) / ▶=ein Schritt zurück (Zeile darunter)",
  "이동 대상 환자가 이미 Exam 탭으로 열려 있으면 그 탭으로 전환되고, 아니면 열면서 이동합니다. Worklist·Image Viewer·Reading Viewer는 열린 환자를 서로 따라갑니다(연동). OK(저장) 시 적용.": "Ist der Zielpatient bereits als Exam-Tab geöffnet, wird dorthin gewechselt, sonst wird er beim Wechsel geöffnet. Worklist, Image Viewer und Reading Viewer folgen einander beim geöffneten Patienten (gekoppelt). Wirksam bei OK (Speichern).",
  "행잉 프로토콜 저장됨 — 왼쪽 ⟳ Refresh 후 뷰어 재오픈 시 적용": "Hanging-Protokoll gespeichert — gilt nach ⟳ Refresh links und erneutem Öffnen des Viewers",
