  "화면이 비거나 오류가 났을 때 자동으로 남는 기록입니다.": "Automatisch erstellte Aufzeichnungen bei leerem Bildschirm oder Fehlern.",
  "새로고침해도 지워지지 않습니다.": "Bleibt auch nach dem Neuladen erhalten.",
