  "협진 연결 수가 한도를 넘었습니다 — 사용하지 않는 뷰어 창을 닫으세요": "Konsil-Verbindungslimit überschritten — ungenutzte Viewer-Fenster schließen",
  "다른 창이 다운로드를 맡고 있습니다.": "Ein anderes Fenster übernimmt den Download.",
  "저장 상한에 도달했습니다 — 자동 삭제가 꺼져 있어 더 받지 않습니다.": "Speicherlimit erreicht — automatisches Löschen ist aus, es wird nichts mehr geladen.",
  "열려 있는 검사만으로 저장 상한을 넘었습니다 — 설정 > 환경 > 영상 취득에서 [지금 비우기] 를 누르거나 저장 상한을 올려야 이어받습니다.": "Allein die geöffneten Untersuchungen überschreiten das Speicherlimit — unter Einstellungen > Umgebung > Bildbezug [Jetzt leeren] drücken oder das Limit erhöhen, um fortzufahren.",
  "저장 상한에 도달했습니다 — 보고 있는 검사는 지우지 않으므로, 뷰어 창을 닫거나 상한을 늘리면 이어받습니다.": "Speicherlimit erreicht — betrachtete Untersuchungen werden nicht gelöscht; Viewer-Fenster schließen oder das Limit erhöhen, um fortzufahren.",
  "뷰어 창이 별도 포트(VITE_VIEWER_BASE)로 뜨는 배치입니다 — 창끼리 저장소를 공유할 수 없어 사용할 수 없습니다.": "In dieser Bereitstellung öffnen Viewer-Fenster auf einem separaten Port (VITE_VIEWER_BASE) — Fenster können keinen Speicher teilen, daher nicht verfügbar.",
  "보안 컨텍스트(HTTPS 또는 localhost)가 아닙니다 — 브라우저가 OPFS 를 막습니다.": "Kein sicherer Kontext (HTTPS oder localhost) — der Browser blockiert OPFS.",
  "이 브라우저는 OPFS(navigator.storage.getDirectory)를 지원하지 않습니다.": "Dieser Browser unterstützt OPFS (navigator.storage.getDirectory) nicht.",
  "이 브라우저는 IndexedDB 를 지원하지 않습니다(저장 인덱스에 필요).": "Dieser Browser unterstützt IndexedDB nicht (für den Speicherindex erforderlich).",
  "이 브라우저는 Window Management API(모니터 감지)를 지원하지 않습니다 — 최신 Chrome/Edge 를 사용하세요.": "Dieser Browser unterstützt die Window Management API (Monitorerkennung) nicht — bitte aktuelles Chrome/Edge verwenden.",
  "STT 전사 실패": "STT-Transkription fehlgeschlagen",
  "이 브라우저는 음성 인식을 지원하지 않습니다 (Chrome 권장 — 또는 설정>AI 기능에서 Whisper 선택)": "Dieser Browser unterstützt keine Spracherkennung (Chrome empfohlen — oder Whisper unter Einstellungen>KI-Funktionen wählen)",
