  "채택 실패": "Übernahme fehlgeschlagen",
  "초대 시 자동으로 줄 기본 권한": "Standardrechte bei Einladung",
  "여기서 정한 것은 기본값입니다. 협진 중에는 협진 페이지에서 참가자마다 켜고 끌 수 있습니다.": "Dies sind Standardwerte. Während der Sitzung können sie je Teilnehmer im Panel umgeschaltet werden.",
  "판독 수정·영상 삭제는 협진으로 절대 위임되지 않습니다 — 목록에 없는 이유입니다.": "Befundbearbeitung und Bildlöschung werden nie delegiert — deshalb fehlen sie hier.",
  "화면 조작 · 발표자": "Bildsteuerung · Präsentator",
  "참가 시 발표자 화면 따라가기 (내가 화면을 만지면 자유 보기로 전환)": "Beim Beitritt dem Präsentator folgen (bei Bildänderung freie Ansicht)",
  "참가자의 권한 요청을 자동 승인": "Rechteanfragen automatisch genehmigen",
  "화면 조작(줌·팬·W/L)은 발표자 1명만 전원에게 송출합니다. 나머지 참가자는 각자 자유롭게 보며, 주석·커서는 항상 전원에게 공유됩니다.": "Nur der Präsentator überträgt die Bildsteuerung (Zoom/Pan/W-L). Andere navigieren frei; Annotationen und Cursor werden immer geteilt.",
  "참여자 표시": "Teilnehmeranzeige",
  "마우스 커서 옆에 참여자 아이디 표시": "Teilnehmer-ID neben dem Mauszeiger anzeigen",
  "참여자별 색으로 커서·툴·글자 구분": "Cursor, Werkzeuge und Text nach Teilnehmerfarbe unterscheiden",
  "화상·음성 네트워크 (STUN/TURN)": "Video-/Audionetz (STUN/TURN)",
  "병원 내부망은 비워 두면 됩니다. 인터넷을 건너는 협진에만 STUN/TURN 을 넣으세요 (JSON 배열).": "Im Krankenhausnetz leer lassen. STUN/TURN nur für Sitzungen über das Internet eintragen (JSON-Array).",
  "계측·주석 그리기 (세션 한정 — 판독에는 Master 채택 시에만 저장)": "Messungen/Annotationen zeichnen (nur Sitzung — nur bei Übernahme durch den Master gespeichert)",
  "텍스트·글쓰기 (세션 한정)": "Text und Schrift (nur Sitzung)",
  "검사 탭 전환·과거 검사 열기": "Studien-Tabs wechseln / Voruntersuchungen öffnen",
  "적용 순서(고정)": "Anwendungsreihenfolge (fest)",
  ": ① 행잉(HP — 선택 시만) → ② Mammo(2D-MG — 선택 시만) → ③ 이 Common 표 → ④ 각 뷰어별 표 → ⑤ 자동 규칙(1×1 등).": ": ① Hanging (HP — nur wenn gewählt) → ② Mammo (2D-MG — nur wenn gewählt) → ③ diese Common-Tabelle → ④ Viewer-Tabelle → ⑤ Automatikregeln (1×1 usw.).",
  "이 표에 해당 모달리티 행이 있으면 세 뷰어(SaintView/I-View/T-View) 모두 이 값을 씁니다. 행이 없으면 그 뷰어의 개별 표를 봅니다.": "Hat diese Tabelle eine Zeile für die Modalität, verwenden alle drei Viewer (SaintView/I-View/T-View) diesen Wert. Andernfalls gilt die eigene Tabelle des Viewers.",
  "규정이 켜져 있을 때만 그 규정을 따릅니다(이 표에 MG 행이 없는 이유).": "gilt nur, solange diese Regel aktiviert ist (deshalb hat diese Tabelle keine MG-Zeile).",
  "행은 그 표에 행이 없는 나머지 모달리티에 적용됩니다 —": "gilt für die übrigen Modalitäten, die in jener Tabelle fehlen —",
  "적용 순서(고정): Common 표에 그 모달리티 행이 있으면 Common 이 우선하고, 없을 때 이 표가 적용됩니다.": "Reihenfolge (fest): Hat die Common-Tabelle eine Zeile für die Modalität, gewinnt Common; diese Tabelle gilt nur, wenn nicht.",
  ")는 아래": ") folgt der unten stehenden",
  "별도 창으로 크게 보기 (다른 모니터로 옮길 수 있습니다)": "In separatem Fenster öffnen (auf anderen Monitor verschiebbar)",
  "팝업이 차단되었습니다 — 이 사이트의 팝업을 허용해 주세요": "Pop-up blockiert — bitte Pop-ups für diese Seite zulassen",
  "협진 패널 숨기기 (오른쪽으로 접기)": "Befundungs-Panel ausblenden (nach rechts einklappen)",
  "협진 패널 펼치기": "Befundungs-Panel einblenden",
  "드래그하면 폭이 바뀝니다 (더블클릭 = 기본 폭)": "Zum Ändern der Breite ziehen (Doppelklick = Standardbreite)",
  "좌우 비율 무시": "L/R-Verhältnis ignorieren",
  "조직 탐지와 무관하게 항상 같은 고정 비율로 가운데 여백 제거 (기본 켬)": "Mittleren Leerraum immer mit demselben festen Verhältnis beschneiden, unabhängig von der Gewebeerkennung (standardmäßig ein)",
  "자동 탐지가 영상마다 실패·지연하면 배치가 들쭉날쭉해집니다 — 켜 두면 항상 같은 모양으로 나옵니다. 해제하면 아래 흉벽 판정(자동 탐지) 규칙을 씁니다.": "Wenn die automatische Erkennung bei manchen Bildern fehlschlägt oder verzögert, wird die Anordnung uneinheitlich — eingeschaltet lassen für ein konsistentes Bild. Abwählen, um die Brustwand-Erkennungsregeln unten zu verwenden.",
  "드래그 = 컬럼 위치 이동 · 오른쪽 가장자리 드래그 = 폭 조절": "Ziehen = Spalte verschieben · rechte Kante ziehen = Breite ändern",
